mapper.select:
SELECT event_id, consumer_name, event_type, processed_at
FROM processed_events
WHERE event_id = #{eventId}
  AND consumer_name = #{consumerName}

SELECT EXISTS (
    SELECT 1
    FROM processed_events
    WHERE event_id = #{eventId}
      AND consumer_name = #{consumerName}
)

mapper.delete:
DELETE FROM processed_events
WHERE event_id = #{eventId}
  AND consumer_name = #{consumerName}
